SET ROLE talus_fn;
CREATE TABLE app.telemetry_frame(tenant_id uuid NOT NULL,telemetry_frame_id uuid NOT NULL,device_id uuid NOT NULL,machine_id uuid NOT NULL,recorded_at timestamptz NOT NULL,latitude_microdegrees integer NOT NULL,longitude_microdegrees integer NOT NULL,speed_mph integer NOT NULL CHECK(speed_mph>=0),fuel_pct integer CHECK(fuel_pct BETWEEN 0 AND 100),engine_hours bigint CHECK(engine_hours>=0),raw_payload jsonb NOT NULL DEFAULT '{}'::jsonb,PRIMARY KEY(tenant_id,telemetry_frame_id),FOREIGN KEY(tenant_id,device_id) REFERENCES app.device(tenant_id,device_id),FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id));
CREATE TABLE app.fleet_alert(tenant_id uuid NOT NULL,fleet_alert_id uuid NOT NULL,machine_id uuid NOT NULL,alert_kind text NOT NULL CHECK(alert_kind IN('geofence_breach','speeding','low_battery','impact')),severity text NOT NULL CHECK(severity IN('low','medium','high','critical')),triggered_at timestamptz NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,PRIMARY KEY(tenant_id,fleet_alert_id),FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id));
CREATE TRIGGER m06_telemetry_append BEFORE UPDATE OR DELETE ON app.telemetry_frame FOR EACH ROW EXECUTE FUNCTION app.enforce_append_only();
CREATE OR REPLACE FUNCTION app.assign_machine_to_booking_item(p_machine uuid,p_item uuid,p_terms uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();x uuid:=gen_random_uuid();i app.booking_item_terms_revision%ROWTYPE;m app.machine%ROWTYPE;BEGIN PERFORM app.require_staff_role('manager');SELECT * INTO i FROM app.booking_item_terms_revision WHERE tenant_id=t AND booking_item_terms_revision_id=p_terms;SELECT * INTO m FROM app.machine WHERE tenant_id=t AND machine_id=p_machine FOR UPDATE;IF NOT FOUND OR m.category_location_id<>i.category_location_id THEN RAISE EXCEPTION 'ASSIGNMENT_INCOMPATIBLE' USING ERRCODE='P0001';END IF;INSERT INTO app.machine_occupancy(tenant_id,machine_occupancy_id,machine_id,booking_item_id,booking_item_terms_revision_id,occupancy_kind,occupancy_range)VALUES(t,x,p_machine,p_item,p_terms,'rental',tstzrange(i.scheduled_start_at,i.scheduled_end_at,'[)'));PERFORM app.append_audit('assignment.created','machine_occupancy',x);RETURN x;END;$$;
CREATE OR REPLACE FUNCTION app.reassign_machine(p_old uuid,p_new uuid,p_item uuid,p_terms uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE x uuid;BEGIN PERFORM app.require_staff_role('manager');DELETE FROM app.machine_occupancy WHERE tenant_id=app.current_context_tenant_id() AND machine_occupancy_id=p_old;SELECT app.assign_machine_to_booking_item(p_new,p_item,p_terms) INTO x;RETURN x;END;$$;
CREATE OR REPLACE FUNCTION app.ingest_telemetry_frame(p_id uuid,p_device uuid,p_at timestamptz,p_lat integer,p_lon integer,p_speed integer,p_fuel integer,p_hours bigint,p_raw jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();m uuid;BEGIN PERFORM app.require_context('device');SELECT machine_id INTO m FROM app.device_installation WHERE tenant_id=t AND device_id=p_device AND removed_at IS NULL;IF NOT FOUND THEN RAISE EXCEPTION 'DEVICE_NOT_BOUND' USING ERRCODE='P0001';END IF;INSERT INTO app.telemetry_frame VALUES(t,p_id,p_device,m,p_at,p_lat,p_lon,p_speed,p_fuel,p_hours,p_raw);IF EXISTS(SELECT 1 FROM app.operating_limit WHERE tenant_id=t AND active AND limit_kind='speed' AND limit_value<p_speed) THEN INSERT INTO app.fleet_alert VALUES(t,gen_random_uuid(),m,'speeding','high',p_at,jsonb_build_object('speed_mph',p_speed));END IF;RETURN p_id;END;$$;
DO $$ DECLARE x text;BEGIN FOREACH x IN ARRAY ARRAY['telemetry_frame','fleet_alert'] LOOP EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY;ALTER TABLE app.%I FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_context_policy ON app.%I USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid())',x,x,x);END LOOP;END;$$;
GRANT SELECT,INSERT,UPDATE,DELETE ON app.telemetry_frame,app.fleet_alert TO talus_fn;
REVOKE ALL ON app.telemetry_frame,app.fleet_alert FROM PUBLIC,talus_staff,talus_api,talus_device;
RESET ROLE;
